window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-67891ea2de4d65cf"]={"versions": [{"id": "FIG-67891ea2de4d65cf", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Activity Diagram), Teilschritt-Spezifikation einer Opaque Action mit Kontrollfluss (Initial Node, Action Node, Activity Final Node, UML-Kommentar).</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Foundation / Classic & Adaptive Platform (<code>AUTOSAR_FO_PRS_E2EProtocol</code>, R24-11). Das Diagramm spezifiziert die atomare Logik des Teilschritts „Increment Counter“ innerhalb der Schutzfunktion <code>E2E_P76Protect()</code> des E2E-Profils 76 (PRS_E2E_01403, PRS_E2E_01404, abgeleitet aus RS_E2E_08539).</li>\n<li><strong>Zweck:</strong> Sicherstellung der Erkennung von Datenverlust, Wiederholungsfehlern und Sequenzfehlern auf Empfängerseite durch zyklische Aktualisierung des Alive-/Sequence-Counters vor der Serialisierung/Übertragung.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivitäts-Kontext:</strong></li>\n<li><code>E2E_P76Protect()</code>: Umschließende API-Funktion / Aktivität (symbolisiert durch das Icon für Sub-Aktivitätszerlegung oben links).</li>\n<li><strong>Zustandsstruktur & Datenobjekte:</strong></li>\n<li><code>State</code>: Zeiger auf die zustandsbehaftete Sender-Struktur <code>E2E_P76ProtectStateType</code>.</li>\n<li><code>State-&gt;Counter</code>: 5-Bit-Zählervariable (<code>uint8</code>-basierter Skalar), definiert im Wertebereich <code>[0x00 .. 0x1F]</code>.</li>\n<li><strong>Modell-Elemente:</strong></li>\n<li><em>Initial Node</em> (schwarzer Vollkreis): Einstiegspunkt des Inkrementierungs-Teilschritts.</li>\n<li><em>Action Node</em> (<code>State-&gt;Counter++</code>): Zustandstransformation des Zählers.</li>\n<li><em>Activity Final Node</em> (Bullauge / Doppelkreis): Terminierung des Einzelschritts.</li>\n<li><em>UML Comment / Note</em>: Normative Randeinschränkung für den Überlauf (<code>After Counter has reached its maximum 0x1F, the next Counter value is 0</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Ausführungsmodell:</strong> Synchroner, rein sequentieller Kontrollfluss ohne Verzweigung oder Parallelisierung innerhalb der E2E-Sende-Pipeline:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Erreichen der Sequenzposition zur Zähleraktualisierung innerhalb von <code>E2E_P76Protect()</code> (nach Initialvalidierung der Eingangsparameter).</li>\n<li><strong>Zustandsübergang:</strong> Inkrementierung des Zählers mit Modulo-32-Arithmetik:</li>\n</ol>\n<p class=\"fig-p\">$$\\text{Counter}_{k+1} = (\\text{Counter}_k + 1) \\pmod{32}$$</p>\n<p class=\"fig-p\">bzw. bei Erreichen von <code>0x1F</code> (31 dezimal) Rücksprung auf <code>0x00</code>.</p>\n<ol class=\"fig-list\">\n<li><strong>Abschluss:</strong> Direkter Übergang zum <em>Activity Final Node</em>; Rückgabe des Kontrollflusses an die Folgeschritte von <code>E2E_P76Protect()</code> (z. B. Einfügen in den PDU-Buffer und CRC-Berechnung).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Fehlerpfade/Callbacks:</strong> Keine asynchronen Events, keine Det-/Dem-Meldungen und keine Fehlerausstiege in diesem isolierten Teilschritt.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Bitbreite & Maskierung (C-Implementierung):</strong></li>\n<li>Da Standard-C-Typen (<code>uint8</code>) bei <code>0xFF</code> überlaufen, erfordert E2E Profile 76 eine explizite 5-Bit-Begrenzung im Treibercode:</li>\n</ul>\n<p class=\"fig-p\">```c</p>\n<p class=\"fig-p\">State->Counter = (State->Counter + 1u) & 0x1FU;</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Reentrancy & Speicherverwaltung:</strong></li>\n<li><code>State</code> muss im nicht-flüchtigen/statischen RAM der sendenden Entität (SW-C bzw. E2E-PduM / Com-Stack) persistiert werden.</li>\n<li><code>E2E_P76Protect()</code> ist bezogen auf denselben <code>State</code> nicht reentrant. Greifen mehrere Tasks oder Preemption-Ebenen auf dieselbe Daten-ID zu, müssen Aufrufe auf Applikations-/Middleware-Ebene gemutext werden.</li>\n<li><strong>API-Vertragsbindung:</strong></li>\n<li>Der Zähler darf nur inkrementiert werden, wenn die Eingangsparameter gültig sind (<code>E2E_E_OK</code>). Bei Parametrierfehlern (<code>E2E_E_INPUTERR_NULL</code>, ungültige Längen) verbleibt <code>State-&gt;Counter</code> unverändert.</li>\n</ul>"}, {"id": "FIG-0891964b7890d927", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Activity Diagram), Teilschritt-Spezifikation einer Opaque Action mit Kontrollfluss (Initial Node, Action Node, Activity Final Node, UML-Kommentar).</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Foundation / Classic & Adaptive Platform (<code>AUTOSAR_FO_PRS_E2EProtocol</code>, R24-11). Das Diagramm spezifiziert die atomare Logik des Teilschritts „Increment Counter“ innerhalb der Schutzfunktion <code>E2E_P76Protect()</code> des E2E-Profils 76 (PRS_E2E_01403, PRS_E2E_01404, abgeleitet aus RS_E2E_08539).</li>\n<li><strong>Zweck:</strong> Sicherstellung der Erkennung von Datenverlust, Wiederholungsfehlern und Sequenzfehlern auf Empfängerseite durch zyklische Aktualisierung des Alive-/Sequence-Counters vor der Serialisierung/Übertragung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivitäts-Kontext:</strong></li>\n<li><code>E2E_P76Protect()</code>: Umschließende API-Funktion / Aktivität (symbolisiert durch das Icon für Sub-Aktivitätszerlegung oben links).</li>\n<li><strong>Zustandsstruktur & Datenobjekte:</strong></li>\n<li><code>State</code>: Zeiger auf die zustandsbehaftete Sender-Struktur <code>E2E_P76ProtectStateType</code>.</li>\n<li><code>State-&gt;Counter</code>: 5-Bit-Zählervariable (<code>uint8</code>-basierter Skalar), definiert im Wertebereich <code>[0x00 .. 0x1F]</code>.</li>\n<li><strong>Modell-Elemente:</strong></li>\n<li><em>Initial Node</em> (schwarzer Vollkreis): Einstiegspunkt des Inkrementierungs-Teilschritts.</li>\n<li><em>Action Node</em> (<code>State-&gt;Counter++</code>): Zustandstransformation des Zählers.</li>\n<li><em>Activity Final Node</em> (Bullauge / Doppelkreis): Terminierung des Einzelschritts.</li>\n<li><em>UML Comment / Note</em>: Normative Randeinschränkung für den Überlauf (<code>After Counter has reached its maximum 0x1F, the next Counter value is 0</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Ausführungsmodell:</strong> Synchroner, rein sequentieller Kontrollfluss ohne Verzweigung oder Parallelisierung innerhalb der E2E-Sende-Pipeline:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Erreichen der Sequenzposition zur Zähleraktualisierung innerhalb von <code>E2E_P76Protect()</code> (nach Initialvalidierung der Eingangsparameter).</li>\n<li><strong>Zustandsübergang:</strong> Inkrementierung des Zählers mit Modulo-32-Arithmetik:</li>\n</ol>\n<p class=\"fig-p\">$$\\text{Counter}_{k+1} = (\\text{Counter}_k + 1) \\pmod{32}$$</p>\n<p class=\"fig-p\">bzw. bei Erreichen von <code>0x1F</code> (31 dezimal) Rücksprung auf <code>0x00</code>.</p>\n<ol class=\"fig-list\">\n<li><strong>Abschluss:</strong> Direkter Übergang zum <em>Activity Final Node</em>; Rückgabe des Kontrollflusses an die Folgeschritte von <code>E2E_P76Protect()</code> (z. B. Einfügen in den PDU-Buffer und CRC-Berechnung).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Fehlerpfade/Callbacks:</strong> Keine asynchronen Events, keine Det-/Dem-Meldungen und keine Fehlerausstiege in diesem isolierten Teilschritt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Bitbreite & Maskierung (C-Implementierung):</strong></li>\n<li>Da Standard-C-Typen (<code>uint8</code>) bei <code>0xFF</code> überlaufen, erfordert E2E Profile 76 eine explizite 5-Bit-Begrenzung im Treibercode:</li>\n</ul>\n<p class=\"fig-p\">```c</p>\n<p class=\"fig-p\">State->Counter = (State->Counter + 1u) & 0x1FU;</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Reentrancy & Speicherverwaltung:</strong></li>\n<li><code>State</code> muss im nicht-flüchtigen/statischen RAM der sendenden Entität (SW-C bzw. E2E-PduM / Com-Stack) persistiert werden.</li>\n<li><code>E2E_P76Protect()</code> ist bezogen auf denselben <code>State</code> nicht reentrant. Greifen mehrere Tasks oder Preemption-Ebenen auf dieselbe Daten-ID zu, müssen Aufrufe auf Applikations-/Middleware-Ebene gemutext werden.</li>\n<li><strong>API-Vertragsbindung:</strong></li>\n<li>Der Zähler darf nur inkrementiert werden, wenn die Eingangsparameter gültig sind (<code>E2E_E_OK</code>). Bei Parametrierfehlern (<code>E2E_E_INPUTERR_NULL</code>, ungültige Längen) verbleibt <code>State-&gt;Counter</code> unverändert.</li>\n</ul>"}], "trans": [{"from": "FIG-67891ea2de4d65cf", "to": "FIG-0891964b7890d927", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
